{id:'VT-ARTS-05',type:'festival flyer',title:'YOUNG ARTISTS FESTIVAL',org:'Sunrise Community Arts Centre',intro:'Celebrate creativity through drawing, music and performance.',date:'12 December 2026',venue:'Sunrise Community Arts Centre',time:'10.00 a.m. to 5.00 p.m.',cards:[['LIVE DRAWING WORKSHOP','Suitable for ages 9 to 12.','Learn to sketch people in motion.','Morning session begins at 10.30 a.m.'],['MINI MUSIC STAGE','Young performers may sign up.','Open to ages 10 to 14.','Registration closes on 5 December.'],['ART MARKET','View and purchase handmade items.','The market opens at 11.00 a.m.','Cashless payment is available.']]},
{id:'VT-HOLIDAY-06',type:'holiday programme',title:'DECEMBER DISCOVERY CAMP',org:'Bright Minds Learning Hub',intro:'Make your school holidays meaningful with hands-on activities and teamwork.',date:'1–4 December 2026',venue:'Bright Minds Learning Hub',time:'9.00 a.m. to 4.00 p.m.',cards:[['DAY 1 · INVENTORS','Design a simple machine with your team.','Open to P5–P6 pupils.','Teams of four are encouraged.'],['DAY 2 · NATURE EXPLORERS','Take part in a guided nature walk.','Wear covered shoes and a cap.','Bring a water bottle.'],['DAY 3 · CREATIVE CODERS','Create an interactive story using block coding.','No previous experience is needed.','The workshop is held in Lab 1.']]}
